package com.signalchain.app
import android.net.Uri;import android.os.Bundle;import androidx.activity.ComponentActivity;import androidx.activity.compose.setContent;import androidx.activity.compose.rememberLauncherForActivityResult;import androidx.activity.result.contract.ActivityResultContracts;import androidx.compose.foundation.layout.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import kotlinx.coroutines.*;import com.signalchain.app.audio.AudioPlayer;import com.signalchain.app.audio.AudioDecoder;import com.signalchain.app.audio.WavWriter;import com.signalchain.app.pipeline.RunPipeline;import java.io.File
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{MaterialTheme{Surface(Modifier.fillMaxSize()){SignalChainScreen()}}}}}
@Composable fun SignalChainScreen(){val ctx=androidx.compose.ui.platform.LocalContext.current;var uri by remember{mutableStateOf<Uri?>(null)};var status by remember{mutableStateOf("No file selected")};var result by remember{mutableStateOf<com.signalchain.app.pipeline.PipelineResult?>(null)};var busy by remember{mutableStateOf(false)};val player=remember{AudioPlayer()};val picker=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){u->uri=u;result=null;status=if(u==null)"No file selected" else "Selected file"};Column(Modifier.fillMaxSize().padding(24.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Text("SignalChain",style=MaterialTheme.typography.headlineMedium);Button(onClick={picker.launch(arrayOf("audio/*"))}){Text("Pick audio file")};Text(status);if(busy)LinearProgressIndicator(Modifier.fillMaxWidth());Button(enabled=uri!=null&&!busy,onClick={busy=true;status="Enhancing…";CoroutineScope(Dispatchers.IO).launch{try{val temp=File.createTempFile("signalchain-input-",".wav",ctx.cacheDir);ctx.contentResolver.openInputStream(uri!!).use{input->temp.outputStream().use{out->input!!.copyTo(out)}};val maxBytes=50L*1024*1024;require(temp.length() in 1..maxBytes){"File is empty or larger than the 50 MB limit."};val isWav=temp.length()>=12&&temp.inputStream().use{s->val magic=ByteArray(4);s.read(magic)==4&&String(magic)=="RIFF"};val wavPath=if(isWav){temp.absolutePath}else{val decoded=AudioDecoder.decodeToMonoPcm(ctx,uri!!);val decodedWav=File.createTempFile("signalchain-decoded-",".wav",ctx.cacheDir);WavWriter.write(decodedWav.absolutePath,decoded.samples,decoded.sampleRate);decodedWav.absolutePath};val r=RunPipeline(ctx).run(wavPath);withContext(Dispatchers.Main){result=r;status="Enhancement complete";busy=false}}catch(e:Exception){withContext(Dispatchers.Main){status=e.message?:"Could not enhance audio file";busy=false}}}}){Text("Run enhancement")};result?.let{r->Text("${r.mode}: ${r.rationale}");Text("SNR: %.2f dB → %.2f dB".format(r.snrBeforeDb,r.snrAfterDb));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick={uri?.let{u->ctx.contentResolver.openInputStream(u)?.use{ins->{val f=File.createTempFile("original-",".wav",ctx.cacheDir);f.outputStream().use{out->ins.copyTo(out)};player.play(f)}}}}){Text("Play original")};Button(onClick={player.play(File(r.outputFilePath))}){Text("Play enhanced")}}}}}
